import React, { useEffect, useRef } from 'react';

/**
 * ENCIRCLE — a film transport.
 *
 * The disc is a glass lens and it is the handle. Drag it across the word and it
 * converts what it passes: drive it right and the letters are left hollow, drive
 * it left and they fill in again. What sits behind the glass is magnified and
 * thrown slightly out of focus, so the lens reads as a thing with depth rather
 * than a grey plate.
 *
 * Push the lens to either end and the word is uniformly one state, which is the
 * moment it prints: a film cell drops out, tumbles, and lands on the floor,
 * keeping the form it was printed in and whatever the chemistry did to it.
 *
 * Dragging is the only action.
 */

const SOLID_SRC = 'data:image/webp;base64,';
const OUTLINE_SRC = 'data:image/webp;base64,';
const MARKS_SRC = 'data:image/webp;base64,';

/* Both letterings are the artwork's own, exported at the same scale and centred
 * on a common canvas, so a single destination rect serves either. */
const ART_W = 1326;
const ART_H = 208;
const ART_ASPECT = ART_W / ART_H;

/* Which side of the lens has been converted. The artwork's own mid-sweep frame
 * reads the other way round; flip this to match it. */
const OUTLINE_IS_LEFT = true;

const LENS_OF_WORD = 0.5;   // lens diameter against the word's width
const LENS_EDGE_GAIN = 0.12; // how much bigger the glass draws things at its rim
const LENS_FALLOFF = 3.0;   // how late that gain arrives, so the middle stays true
const LENS_RINGS = 32;      // concentric bands the warp is built from
const LENS_BLUR = 0.014;    // of the lens radius; the rim softens further on its own
const WORD_CENTRE_Y = 0.34;
const FLOOR_Y = 0.86;

const CARD_OF_WORD = 0.46;  // a printed cell against the word's width
const CARD_FILL = '#d8c9ae';
const CARD_EDGE = '#b9a684';
const SPROCKET = '#2a2622';
const BACKDROP = '#f1efe9';

/* The supplied colourway card. Of the codes printed on it, bone, brass and
 * charcoal are valid RGB and match their swatches; red velvet's reads 268 on a
 * channel and buttercream's reads yellow-green against a warm swatch, so those
 * two are sampled from the swatches instead. */
const RED_VELVET = '#b5402e';   // sampled
const BONE_DRY = '#f0eed4';     // as printed
const BUTTERCREAM = '#c9a77c';  // sampled
const AGED_BRASS = '#59431a';   // as printed
const CHARCOAL = '#03060a';     // as printed

/* What the developing bath did to each cell: pairs drawn from that card, kept
 * inside the one warm family so no cell jumps out of the set. Bone and
 * buttercream only ever appear as the far end of a fade, since on a tan base
 * they would otherwise read as no ink at all. */
const TINTS: [string, string][] = [
  [CHARCOAL, AGED_BRASS],
  [AGED_BRASS, RED_VELVET],
  [RED_VELVET, AGED_BRASS],
  [CHARCOAL, RED_VELVET],
  [AGED_BRASS, BUTTERCREAM],
  [RED_VELVET, BONE_DRY],
  [CHARCOAL, '#2b2722'],
];

const GRAIN = 0.065;         // film grain over the whole frame
const GRAVITY = 1650;
const MAX_CELLS = 16;
const FLOOR_BAND = 0.05;     // the floor is a band, so cells scatter instead of queueing
const GROUND_DRAG = 3.2;    // how quickly a sliding cell gives up
const PUSH = 0.2;          // how hard two cells shove each other apart
const TICKS = 8;            // index marks around the lens, and so clicks per turn
const TINT_W = 663;         // the cached tint is built at half the artwork's size
const TINT_H = 104;

type Cell = {
  outline: boolean;
  age: number; restRot: number;
  x: number; y: number; vx: number; vy: number;
  rot: number; spin: number;
  scale: number;
  bounces: number;
  landed: boolean;
  flat: number;            // 0 in the air, 1 settled; drives the contact shadow
  mottle: number;          // this cell's own patch of uneven emulsion
  restY: number;           // where this one comes to rest in the floor band
  held: boolean;           // the pointer has picked it up
  art: HTMLCanvasElement | null;
};

/* ---------------- sound ---------------- */

let audio: AudioContext | null = null;
function ctx() {
  const AC = window.AudioContext || (window as any).webkitAudioContext;
  if (!audio) audio = new AC();
  if (audio.state === 'suspended') audio.resume();
  return audio;
}

/** A sprocket passing the gate: a dry tick, barely there. */
function tick() {
  try {
    const c = ctx(), t = c.currentTime;
    const n = Math.floor(c.sampleRate * 0.012);
    const buf = c.createBuffer(1, n, c.sampleRate);
    const d = buf.getChannelData(0);
    for (let i = 0; i < n; i++) d[i] = (Math.random() * 2 - 1) * (1 - i / n) ** 2;
    const src = c.createBufferSource(); src.buffer = buf;
    const bp = c.createBiquadFilter(); bp.type = 'bandpass'; bp.frequency.value = 2600; bp.Q.value = 1.4;
    const g = c.createGain(); g.gain.value = 0.05;
    src.connect(bp).connect(g).connect(c.destination);
    src.start(t);
  } catch { /* sound is optional */ }
}

/** The cell releasing: a shutter clack with a little body under it. */
function clack() {
  try {
    const c = ctx(), t = c.currentTime;
    const o = c.createOscillator(), g = c.createGain();
    o.type = 'triangle';
    o.frequency.setValueAtTime(180, t);
    o.frequency.exponentialRampToValueAtTime(60, t + 0.09);
    g.gain.setValueAtTime(0.0001, t);
    g.gain.exponentialRampToValueAtTime(0.3, t + 0.006);
    g.gain.exponentialRampToValueAtTime(0.0001, t + 0.16);
    o.connect(g).connect(c.destination);
    o.start(t); o.stop(t + 0.18);

    const n = Math.floor(c.sampleRate * 0.05);
    const buf = c.createBuffer(1, n, c.sampleRate);
    const d = buf.getChannelData(0);
    for (let i = 0; i < n; i++) d[i] = (Math.random() * 2 - 1) * (1 - i / n);
    const src = c.createBufferSource(); src.buffer = buf;
    const hp = c.createBiquadFilter(); hp.type = 'highpass'; hp.frequency.value = 900;
    const ng = c.createGain(); ng.gain.value = 0.16;
    src.connect(hp).connect(ng).connect(c.destination);
    src.start(t);
  } catch { /* sound is optional */ }
}

const rand = (a: number, b: number) => a + Math.random() * (b - a);
const pick = <T,>(xs: T[]) => xs[Math.floor(Math.random() * xs.length)];

/* ---------------- component ---------------- */

export default function App() {
  const canvasRef = useRef<HTMLCanvasElement>(null);

  useEffect(() => {
    const el = canvasRef.current;
    if (!el) return;
    const context = el.getContext('2d');
    if (!context) return;
    // bound once, so the nested helpers below need no non-null assertions
    const canvas: HTMLCanvasElement = el;
    const g: CanvasRenderingContext2D = context;
    const canBlur = typeof g.filter === 'string';

    const images: Record<string, HTMLImageElement> = {};
    let ready = false;
    let raf = 0;
    let last = 0;

    /* sweep state */
    let targetHead = 0;
    let hintAlpha = 1, hintDismissed = false;
    let headVelocity = 0;
    let head = 0;              // 0 at the word's left edge, 1 at its right
    let dragging = false;      // the lens is being driven
    let grabOffset = 0;
    let heldCell: Cell | null = null;
    let heldDX = 0, heldDY = 0;
    let lastPx = 0, lastPy = 0, lastPt = 0;
    let printedAt: 'left' | 'right' | null = 'left';
    let activePointer: number | null = null;
    let wordDirty = true;
    let disposed = false;
    let lastTickIndex = 0;

    const cells: Cell[] = [];

    /* layout, recomputed on resize */
    let W = 0, H = 0;
    let wordW = 0, wordH = 0, wordX = 0, wordY = 0;
    let lensD = 0, lensR = 0;

    // The word is drawn once into its own layer each frame. The lens then samples
    // that layer ring by ring, so the warp costs a handful of blits instead of
    // re-drawing and re-clipping the lettering dozens of times.
    const sharp = document.createElement('canvas');
    const soft = document.createElement('canvas');
    const sharpG = sharp.getContext('2d');
    const softG = soft.getContext('2d');

    // One tile of emulsion grain, laid over everything at the end of each frame.
    const grainTile = document.createElement('canvas');
    grainTile.width = grainTile.height = 168;
    {
      const q = grainTile.getContext('2d');
      if (q) {
        const px = q.createImageData(168, 168);
        for (let i = 0; i < px.data.length; i += 4) {
          const v = 126 + (Math.random() * 2 - 1) * 62;
          px.data[i] = v;
          px.data[i + 1] = v * 0.98;
          px.data[i + 2] = v * 0.94;   // grain leans warm, like film base
          px.data[i + 3] = 255;
        }
        q.putImageData(px, 0, 0);
      }
    }
    const grain = g.createPattern(grainTile, 'repeat');

    function layout() {
      const dpr = Math.min(window.devicePixelRatio || 1, 2);
      const oldW = W, oldH = H;
      W = Math.max(1, canvas.clientWidth);
      H = Math.max(1, canvas.clientHeight);
      if (oldW && oldH) for (const c of cells) { c.x *= W / oldW; c.y *= H / oldH; c.restY *= H / oldH; }
      wordDirty = true;
      canvas.width = Math.max(1, Math.round(W * dpr));
      canvas.height = Math.max(1, Math.round(H * dpr));
      g.setTransform(dpr, 0, 0, dpr, 0, 0);

      // The lens travels to both ends of the word, so the word has to leave a
      // clear radius either side or the lens is cut off by the edge of the stage.
      // With the lens half the word's width, that caps the word at two thirds of it.
      wordW = Math.min(W / 1.6, H * 1.0);
      wordH = wordW / ART_ASPECT;
      wordX = (W - wordW) / 2;
      wordY = H * WORD_CENTRE_Y - wordH / 2;
      lensD = wordW * LENS_OF_WORD;
      lensR = lensD / 2;

      for (const layer of [sharp, soft]) {
        layer.width = canvas.width;
        layer.height = canvas.height;
      }
      sharpG?.setTransform(dpr, 0, 0, dpr, 0, 0);
      softG?.setTransform(dpr, 0, 0, dpr, 0, 0);
    }

    const headPx = () => wordX + head * wordW;

    /* ---------------- the word ---------------- */

    /** Draws the word split at `cut`: one state to its left, the other to its right. */
    function drawWord(q: CanvasRenderingContext2D, x: number, y: number, w: number, h: number, cut: number) {
      const solid = images.solid, outline = images.outline;
      if (!solid || !outline) return;
      const leftImg = OUTLINE_IS_LEFT ? outline : solid;
      const rightImg = OUTLINE_IS_LEFT ? solid : outline;

      q.save();
      q.beginPath();
      q.rect(x - w, y - h * 2, Math.max(0, cut - x) + w, h * 5);
      q.clip();
      q.drawImage(leftImg, x, y, w, h);
      q.restore();

      q.save();
      q.beginPath();
      q.rect(cut, y - h * 2, Math.max(0, x + w - cut) + w, h * 5);
      q.clip();
      q.drawImage(rightImg, x, y, w, h);
      q.restore();
    }

    /* ---------------- printed cells ---------------- */

    /** Bakes one cell's lettering with its own gradient, so only the strokes carry colour. */
    function buildArt(outline: boolean): HTMLCanvasElement | null {
      const img = outline ? images.outline : images.solid;
      if (!img) return null;
      const c = document.createElement('canvas');
      c.width = TINT_W; c.height = TINT_H;
      const q = c.getContext('2d');
      if (!q) return null;
      q.drawImage(img, 0, 0, TINT_W, TINT_H);
      // source-in keeps the gradient only where there is ink
      q.globalCompositeOperation = 'source-in';
      const [a, b] = pick(TINTS);
      const ang = rand(0, Math.PI * 2);
      const dx = Math.cos(ang) * TINT_W * 0.5, dy = Math.sin(ang) * TINT_H * 0.5;
      const grad = q.createLinearGradient(TINT_W / 2 - dx, TINT_H / 2 - dy, TINT_W / 2 + dx, TINT_H / 2 + dy);
      grad.addColorStop(0, a);
      grad.addColorStop(1, b);
      q.fillStyle = grad;
      q.fillRect(0, 0, TINT_W, TINT_H);
      return c;
    }

    function roundRect(x: number, y: number, w: number, h: number, r: number) {
      g.beginPath();
      g.moveTo(x + r, y);
      g.arcTo(x + w, y, x + w, y + h, r);
      g.arcTo(x + w, y + h, x, y + h, r);
      g.arcTo(x, y + h, x, y, r);
      g.arcTo(x, y, x + w, y, r);
      g.closePath();
    }

    function cardSize(c: Cell) {
      const cardW = wordW * CARD_OF_WORD * c.scale;
      const innerW = cardW * 0.84;
      const innerH = innerW / ART_ASPECT;
      return { cardW, innerW, innerH, cardH: innerH / 0.56 };
    }

    /** A developed cell: film base, sprocket strips, and the word it caught. */
    function drawCell(c: Cell) {
      const { cardW, innerW, innerH, cardH } = cardSize(c);

      // Contact shadow. On the floor it sits tight under the cell; in the air it
      // stays behind and spreads, so you can read the height off it.
      const lift = Math.min(1, Math.max(0, (c.restY - c.y) / (H * .48)));
      g.save();
      g.translate(c.x, c.restY + cardH * .15);
      g.rotate(c.rot);
      const sh = g.createRadialGradient(0, 0, 1, 0, 0, cardW * 0.56);
      const dark = (0.25 - lift * 0.19) * Math.min(1, c.age / .28);
      sh.addColorStop(0, `rgba(74,62,46,${dark})`);
      sh.addColorStop(0.6, `rgba(74,62,46,${dark * 0.42})`);
      sh.addColorStop(1, 'rgba(74,62,46,0)');
      g.fillStyle = sh;
      g.save();
      g.scale(1, 0.3 + lift * 0.3);
      g.fillRect(-cardW * 0.56, -cardW * 0.56, cardW * 1.12, cardW * 1.12);
      g.restore();
      g.restore();

      g.save();
      g.translate(c.x, c.y);
      g.rotate(c.rot);
      const feed = Math.min(1, c.age / .28);
      const easedFeed = 1 - Math.pow(1 - feed, 3);
      g.translate(-cardW / 2, -cardH / 2);
      g.beginPath(); g.rect(0, 0, cardW * easedFeed, cardH); g.clip();

      const stock = g.createLinearGradient(0, 0, cardW, cardH);
      stock.addColorStop(0, '#deca9f'); stock.addColorStop(.46, '#ead9b5'); stock.addColorStop(1, '#bda077');
      g.fillStyle = stock;
      roundRect(0, 0, cardW, cardH, cardH * 0.06);
      g.fill();

      // uneven emulsion: a soft wash that differs from cell to cell
      g.save();
      roundRect(0, 0, cardW, cardH, cardH * 0.06);
      g.clip();
      const wash = g.createLinearGradient(
        Math.sin(c.mottle) * cardW, 0,
        cardW - Math.sin(c.mottle) * cardW, cardH,
      );
      wash.addColorStop(0, 'rgba(255,250,235,0.5)');
      wash.addColorStop(0.5, 'rgba(188,170,138,0.16)');
      wash.addColorStop(1, 'rgba(120,102,74,0.22)');
      g.fillStyle = wash;
      g.fillRect(0, 0, cardW, cardH);
      if (grain) {
        g.globalAlpha = 0.3;
        g.globalCompositeOperation = 'overlay';
        g.translate(c.mottle % 168, (c.mottle * 1.7) % 168);
        g.fillStyle = grain;
        g.fillRect(-168, -168, cardW + 336, cardH + 336);
      }
      g.restore();

      g.strokeStyle = CARD_EDGE;
      g.lineWidth = 1;
      roundRect(0, 0, cardW, cardH, cardH * 0.06);
      g.stroke();

      const strip = cardH * 0.2;
      const hw = cardW * 0.042, hh = strip * 0.42;
      const count = Math.max(4, Math.round(cardW / (hw * 2.1)));
      const gap = (cardW - count * hw) / (count + 1);
      g.fillStyle = SPROCKET;
      for (let i = 0; i < count; i++) {
        const hx = gap + i * (hw + gap);
        roundRect(hx, (strip - hh) / 2, hw, hh, hh * 0.22); g.fill();
        roundRect(hx, cardH - strip + (strip - hh) / 2, hw, hh, hh * 0.22); g.fill();
      }

      g.strokeStyle = 'rgba(92,62,27,.34)'; g.lineWidth = .7;
      roundRect(cardW * .065, strip, cardW * .87, cardH - strip * 2, 1.5); g.stroke();
      // Tiny edge codes are printed with the emulsion, outside the artwork.
      g.fillStyle = '#6f492c'; g.font = `${Math.max(5, cardH * .068)}px monospace`;
      g.fillText(c.outline ? 'ENC / NEGATIVE' : 'ENC / POSITIVE', cardW * .07, cardH * .78);
      if (c.art) g.drawImage(c.art, (cardW - innerW) / 2, (cardH - innerH) / 2, innerW, innerH);
      g.restore();
    }

    /* ---------------- the lens ---------------- */

    /**
     * How much the glass magnifies at a given distance out from its centre.
     * True to size through the middle, then climbing hard towards the rim, so a
     * ring near the edge reaches only a little way out for its content and blows
     * it up to fill the band. Shapes caught there swell and smear along the
     * circle, which is the arc stretch at the edge of real glass.
     */
    function magAt(t: number) {
      return 1.045 + LENS_EDGE_GAIN * Math.pow(t, LENS_FALLOFF);
    }

    function drawLens() {
      const cx = headPx();
      const cy = wordY + wordH / 2;

      g.save();
      g.beginPath(); g.arc(cx, cy, lensR, 0, Math.PI * 2); g.clip();
      g.fillStyle = BACKDROP; g.fillRect(cx - lensR, cy - lensR, lensD, lensD);
      g.restore();
      if (softG) {
        for (let k = 0; k < LENS_RINGS; k++) {
          const t0 = k / LENS_RINGS;
          const t1 = (k + 1) / LENS_RINGS;
          const m = magAt((t0 + t1) / 2);
          g.save();
          g.beginPath();
          // an annulus, cut as an outer disc minus the inner one
          g.arc(cx, cy, t1 * lensR, 0, Math.PI * 2);
          if (k > 0) {
            g.moveTo(cx + t0 * lensR, cy);
            g.arc(cx, cy, t0 * lensR, 0, Math.PI * 2, true);
          }
          g.clip('evenodd');
          const pixelRatio = soft.width / W;
          g.drawImage(soft,
            (cx - lensR / m) * pixelRatio, (cy - lensR / m) * pixelRatio,
            lensD / m * pixelRatio, lensD / m * pixelRatio,
            cx - lensR, cy - lensR, lensD, lensD);
          g.restore();
        }
      }

      // The glass itself is almost colourless. It shows as a faint lift over the
      // whole disc and as light gathering hard against the rim.
      g.save();
      g.beginPath();
      g.arc(cx, cy, lensR, 0, Math.PI * 2);
      g.clip();

      const veil = g.createRadialGradient(cx, cy, lensR * 0.05, cx, cy, lensR);
      veil.addColorStop(0, 'rgba(255,255,255,0.04)');
      veil.addColorStop(0.62, 'rgba(255,255,255,0.08)');
      veil.addColorStop(0.86, 'rgba(255,255,255,0.16)');
      veil.addColorStop(0.97, 'rgba(255,255,255,0.5)');
      veil.addColorStop(1, 'rgba(255,255,255,0.36)');
      g.fillStyle = veil;
      g.fillRect(cx - lensR, cy - lensR, lensD, lensD);

      // the two bright blooms a round lens throws out to its sides
      for (const side of [-1, 1]) {
        const bloom = g.createRadialGradient(
          cx + side * lensR * 0.9, cy, lensR * 0.04,
          cx + side * lensR * 0.9, cy, lensR * 0.6,
        );
        bloom.addColorStop(0, 'rgba(255,255,255,0.18)');
        bloom.addColorStop(1, 'rgba(255,255,255,0)');
        g.fillStyle = bloom;
        g.fillRect(cx - lensR, cy - lensR, lensD, lensD);
      }
      g.restore();

      // a thin lit edge all the way round
      g.save();
      g.lineWidth = Math.max(1, lensR * 0.012);
      g.strokeStyle = 'rgba(255,255,255,0.85)';
      g.beginPath();
      g.arc(cx, cy, lensR - g.lineWidth * 0.5, 0, Math.PI * 2);
      g.stroke();
      g.strokeStyle = 'rgba(150,150,150,0.3)';
      g.lineWidth = 1;
      g.beginPath();
      g.arc(cx, cy, lensR, 0, Math.PI * 2);
      g.stroke();
      g.restore();

      g.save();
      g.lineCap = 'round'; g.lineWidth = Math.max(2, lensR * .016);
      g.strokeStyle = 'rgba(255,255,255,.8)';
      g.beginPath(); g.arc(cx, cy, lensR * .963, Math.PI * 1.08, Math.PI * 1.68); g.stroke();
      g.lineWidth = lensR * .032; g.strokeStyle = 'rgba(255,255,255,.24)';
      g.beginPath(); g.arc(cx, cy, lensR * .92, Math.PI * 1.13, Math.PI * 1.6); g.stroke();
      g.restore();
      // the index marks, which ride on the glass and roll with it
      const marks = images.marks;
      if (marks) {
        g.save();
        g.translate(cx, cy);
        g.rotate((cx - wordX) / lensR);
        g.drawImage(marks, -lensR, -lensR, lensD, lensD);
        g.restore();
      }
    }

    function render() {
      // the word on its own layer, plus a blurred copy for the glass to sample
      if (wordDirty && sharpG && softG) {
        wordDirty = false;
        sharpG.clearRect(0, 0, W, H);
        drawWord(sharpG, wordX, wordY, wordW, wordH, headPx());
        softG.clearRect(0, 0, W, H);
        softG.save();
        if (canBlur) softG.filter = `blur(${Math.max(2, lensR * LENS_BLUR)}px)`;
        softG.drawImage(sharp, 0, 0, W, H);
        softG.restore();
      }

      g.fillStyle = BACKDROP;
      g.fillRect(0, 0, W, H);
      for (const c of cells) drawCell(c);
      if (sharpG) g.drawImage(sharp, 0, 0, W, H);
      else drawWord(g, wordX, wordY, wordW, wordH, headPx());
      drawLens();
      // A local direction cue, tied to the handle rather than gallery navigation.
      if (hintAlpha > 0) {
        g.save();
        g.globalAlpha = hintAlpha * .70;
        g.fillStyle = '#5d5a53';
        g.font = '12px "Courier New", monospace';
        g.textAlign = 'center';
        g.textBaseline = 'middle';
        g.fillText('←  Drag  →', headPx(), wordY + wordH / 2 + lensR + 25);
        g.restore();
      }
      canvas.dataset.dragHint = hintAlpha.toFixed(3);

      // the whole frame sits on one stock, so the grain goes over everything
      if (grain) {
        g.save();
        g.globalCompositeOperation = 'overlay';
        g.globalAlpha = GRAIN;
        g.fillStyle = grain;
        g.fillRect(0, 0, W, H);
        g.restore();
      }
      const vig = g.createRadialGradient(
        W / 2, H * 0.44, Math.min(W, H) * 0.26,
        W / 2, H * 0.44, Math.max(W, H) * 0.78,
      );
      vig.addColorStop(0, 'rgba(0,0,0,0)');
      vig.addColorStop(1, 'rgba(62,52,38,0.17)');
      g.fillStyle = vig;
      g.fillRect(0, 0, W, H);
    }

    /* ---------------- printing and falling ---------------- */

    function print(outline: boolean) {
      cells.push({
        outline, age: 0, restRot: rand(-.23, .23),
        x: headPx() + rand(-wordW * 0.06, wordW * 0.06),
        y: wordY + wordH / 2,
        vx: head > .5 ? rand(-130, -55) : rand(55, 130),
        vy: 35,
        rot: rand(-0.26, 0.26),
        spin: rand(-.7, .7),
        scale: rand(.92, 1.03),
        bounces: 0,
        landed: false,
        flat: 0,
        mottle: Math.random() * 1000,
        restY: H * FLOOR_Y + rand(-FLOOR_BAND, FLOOR_BAND) * H * 0.5,
        held: false,
        art: buildArt(outline),
      });
      while (cells.length > MAX_CELLS) cells.shift();
      clack();
    }

    /** Three circles along the long axis stand in for the card's shape. */
    function nodes(c: Cell) {
      const { cardW, cardH } = cardSize(c);
      const r = cardH * 0.5;
      const cos = Math.cos(c.rot), sin = Math.sin(c.rot);
      return [-0.33, 0, 0.33].map((t) => ({
        x: c.x + cos * cardW * t,
        y: c.y + sin * cardW * t,
        r,
      }));
    }

    /** Settled cells shove each other aside rather than stacking in one place. */
    function separate() {
      for (let i = 0; i < cells.length; i++) {
        for (let j = i + 1; j < cells.length; j++) {
          const A = cells[i], B = cells[j];
          if (!A.landed || !B.landed) continue;
          const na = nodes(A), nb = nodes(B);
          let px = 0, py = 0, hits = 0;
          for (const a of na) for (const b of nb) {
            const dx = b.x - a.x, dy = b.y - a.y;
            const d = Math.hypot(dx, dy) || 0.0001;
            const overlap = a.r + b.r - d;
            if (overlap > 0) { px += (dx / d) * overlap; py += (dy / d) * overlap; hits++; }
          }
          if (!hits) continue;
          px = (px / hits) * PUSH;
          py = (py / hits) * PUSH * 0.45;
          // a held cell is immovable, so the other one yields all of it
          if (A.held && B.held) continue;
          if (A.held) { B.x += px; B.y += py; }
          else if (B.held) { A.x -= px; A.y -= py; }
          else { A.x -= px * 0.5; A.y -= py * 0.5; B.x += px * 0.5; B.y += py * 0.5; }
        }
      }
    }

    function step(dt: number) {
      let moving = false;
      if (hintDismissed && hintAlpha > 0) { hintAlpha = Math.max(0, hintAlpha - dt * 1.6); moving = hintAlpha > 0; }
      // A critically damped carriage follows the hand; it never jumps on press.
      const error = targetHead - head;
      headVelocity += (error * 600 - headVelocity * 48) * dt;
      if (Math.abs(error) > .00004 || Math.abs(headVelocity) > .0001) {
        moving = true;
        setHead(head + headVelocity * dt);
        if (Math.abs(targetHead - head) < .0005 && Math.abs(headVelocity) < .003) { setHead(targetHead); headVelocity = 0; }
      }

      for (const c of cells) {
        c.age += dt;
        if (c.age < .28) { moving = true; continue; }
        if (c.held) {
          moving = true;
          c.flat += (0 - c.flat) * Math.min(1, dt * 9); // picked up, it stands again
          continue;
        }

        if (!c.landed) {
          moving = true;
          c.vy += GRAVITY * dt;
          c.y += c.vy * dt;
          c.rot += c.spin * dt;
          if (c.y >= c.restY) {
            hintDismissed = true;
            if (c.bounces < 1 && c.vy > 420) {
              c.y = c.restY;
              c.vy *= -0.32;
              c.vx *= 0.6;
              c.spin *= 0.4;
              c.bounces++;
            } else {
              c.y = c.restY;
              c.vy = 0;
              c.landed = true;
              c.spin *= .25;
              c.restRot = Math.max(-.32, Math.min(.32, c.rot));
            }
          }
        } else {
          const rotError = c.restRot - c.rot;
          c.spin += (rotError * 75 - c.spin * 13) * dt;
          c.rot += c.spin * dt;
          if (Math.abs(rotError) > .001 || Math.abs(c.spin) > .003) moving = true;
          // settled: slide to a stop and drift back into the floor band
          c.y += (c.restY - c.y) * Math.min(1, dt * 6);
          if (Math.abs(c.vx) > 1) moving = true;
        }
        // lying down is a slow give rather than a snap
        const want = c.landed ? 1 : 0;
        if (c.flat !== want) {
          c.flat += (want - c.flat) * Math.min(1, dt * 7);
          if (Math.abs(want - c.flat) < 0.004) c.flat = want; else moving = true;
        }

        c.x += c.vx * dt;
        c.vx *= Math.exp(-(c.landed ? GROUND_DRAG : 0.25) * dt);

        const half = cardSize(c).cardW * 0.42;
        if (c.x < half) { c.x = half; c.vx = Math.abs(c.vx) * 0.35; }
        if (c.x > W - half) { c.x = W - half; c.vx = -Math.abs(c.vx) * 0.35; }
      }
      separate();
      return moving;
    }

    function loop(now: number) {
      raf = 0;
      const dt = Math.min(0.1, (now - last) / 1000 || 0.016);
      last = now;
      let moving = false;
      const steps = Math.max(1, Math.ceil(dt / .00833));
      for (let i = 0; i < steps; i++) moving = step(dt / steps) || moving;
      render();
      if (moving || dragging) raf = requestAnimationFrame(loop);
    }
    function kick() {
      if (!raf) { last = performance.now(); raf = requestAnimationFrame(loop); }
    }

    /* ---------------- input ---------------- */

    function setHead(next: number) {
      const clamped = Math.max(0, Math.min(1, next));
      if (clamped === head) return;
      head = clamped;
      wordDirty = true;

      const turns = ((headPx() - wordX) / lensR) / (Math.PI * 2);
      const idx = Math.round(turns * TICKS);
      if (idx !== lastTickIndex) { lastTickIndex = idx; tick(); }

      if (head >= 0.999 && printedAt !== 'right') {
        printedAt = 'right';
        print(OUTLINE_IS_LEFT);
      } else if (head <= 0.001 && printedAt !== 'left') {
        printedAt = 'left';
        print(!OUTLINE_IS_LEFT);
      } else if (head > 0.045 && head < 0.955) {
        printedAt = null;
      }
    }

    const local = (e: PointerEvent) => {
      const r = canvas.getBoundingClientRect();
      return { x: e.clientX - r.left, y: e.clientY - r.top };
    };

    /** Is this point inside the card, allowing for how it came to rest? */
    function hitCell(x: number, y: number) {
      for (let i = cells.length - 1; i >= 0; i--) {
        const c = cells[i];
        const { cardW, cardH } = cardSize(c);
        const dx = x - c.x, dy = y - c.y;
        const cos = Math.cos(-c.rot), sin = Math.sin(-c.rot);
        const lx = dx * cos - dy * sin, ly = dx * sin + dy * cos;
        if (Math.abs(lx) <= cardW / 2 && Math.abs(ly) <= cardH / 2) return c;
      }
      return null;
    }

    function onDown(e: PointerEvent) {
      if (!ready || activePointer !== null) return;
      const { x, y } = local(e);
      const cy = wordY + wordH / 2;
      const onLens = Math.hypot(x - headPx(), y - cy) <= lensR;

      if (!onLens) {
        const c = hitCell(x, y);
        if (c) {
          activePointer = e.pointerId;
          heldCell = c;
          c.held = true;
          heldDX = c.x - x; heldDY = c.y - y;
          lastPx = x; lastPy = y; lastPt = performance.now();
          // whatever you pick up comes to the top of the heap
          cells.splice(cells.indexOf(c), 1);
          cells.push(c);
          try { canvas.setPointerCapture(e.pointerId); } catch { /* synthetic pointer */ }
          kick();
          return;
        }
      }

      const onBand = Math.abs(y - cy) <= Math.max(lensR, wordH);
      if (!onLens && !onBand) return;
      activePointer = e.pointerId;
      dragging = true;
      canvas.style.cursor = "grabbing";
      grabOffset = x - headPx();
      try { canvas.setPointerCapture(e.pointerId); } catch { /* synthetic pointer */ }
      kick();
    }

    function onMove(e: PointerEvent) {
      const { x, y } = local(e);
      if (activePointer !== null && e.pointerId !== activePointer) return;
      if (heldCell) {
        const now = performance.now();
        const dt = Math.max(0.001, (now - lastPt) / 1000);
        heldCell.vx = heldCell.vx * .45 + ((x - lastPx) / dt) * .55;
        heldCell.vy = heldCell.vy * .45 + ((y - lastPy) / dt) * .55;
        lastPx = x; lastPy = y; lastPt = now;
        heldCell.x = x + heldDX;
        heldCell.y = y + heldDY;
        kick();
        return;
      }
      if (dragging) { targetHead = Math.max(0, Math.min(1, (x - grabOffset - wordX) / wordW)); kick(); return; }
      const overLens = Math.hypot(x - headPx(), y - (wordY + wordH / 2)) <= lensR;
      canvas.style.cursor = overLens || hitCell(x, y) ? 'grab' : 'default';
    }

    function onUp(e: PointerEvent) {
      if (e.pointerId !== activePointer) return;
      try { canvas.releasePointerCapture(e.pointerId); } catch {}
      activePointer = null;
      canvas.style.cursor = 'grab';
      if (heldCell) {
        // let go and it falls back to the floor, carrying the throw
        heldCell.held = false;
        heldCell.landed = false;
        heldCell.bounces = 0;
        heldCell.restY = H * FLOOR_Y + rand(-FLOOR_BAND, FLOOR_BAND) * H * 0.5;
        heldCell.vx = Math.max(-900, Math.min(900, heldCell.vx * 0.5));
        heldCell.vy = Math.max(-700, Math.min(700, heldCell.vy * 0.4));
        heldCell.spin = Math.max(-3, Math.min(3, heldCell.vx / 260));
        heldCell = null;
        kick();
      }
      dragging = false;
    }

    canvas.addEventListener('pointerdown', onDown);
    canvas.addEventListener('pointermove', onMove);
    canvas.addEventListener('pointerup', onUp);
    canvas.addEventListener('pointercancel', onUp);

    const ro = new ResizeObserver(() => { layout(); if (ready) render(); });
    ro.observe(canvas);

    /* ---------------- load ---------------- */

    const sources: [string, string][] = [
      ['solid', SOLID_SRC], ['outline', OUTLINE_SRC], ['marks', MARKS_SRC],
    ];
    let pending = sources.length;
    const done = () => { if (disposed) return; if (--pending === 0) { ready = true; layout(); render(); } };
    for (const [key, src] of sources) {
      const img = new Image();
      img.onload = () => { images[key] = img; done(); };
      img.onerror = done;
      img.src = src;
    }
    layout();

    return () => {
      disposed = true;
      cancelAnimationFrame(raf);
      ro.disconnect();
      canvas.removeEventListener('pointerdown', onDown);
      canvas.removeEventListener('pointermove', onMove);
      canvas.removeEventListener('pointerup', onUp);
      canvas.removeEventListener('pointercancel', onUp);
    };
  }, []);

  return (
    <main style={{ margin: 0, width: '100%', height: '100dvh', background: BACKDROP }}>
      <canvas
        ref={canvasRef}
        style={{ display: 'block', width: '100%', height: '100%', touchAction: 'none', userSelect: 'none' }}
      />
    </main>
  );
}
